import{_ as o,o as r,c as l,ag as n}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"이 강의가 다루는 것","slug":"이-강의가-다루는-것","link":"#이-강의가-다루는-것","children":[]},{"level":2,"title":"한국사상의 큰 흐름","slug":"한국사상의-큰-흐름","link":"#한국사상의-큰-흐름","children":[]},{"level":2,"title":"삼국시대: 유교·불교·도교의 유입","slug":"삼국시대-유교·불교·도교의-유입","link":"#삼국시대-유교·불교·도교의-유입","children":[]},{"level":2,"title":"고려시대: 성리학의 수용과 선종의 대두","slug":"고려시대-성리학의-수용과-선종의-대두","link":"#고려시대-성리학의-수용과-선종의-대두","children":[]},{"level":2,"title":"조선시대: 성리학 이념 위의 건국과 그 이후의 전개","slug":"조선시대-성리학-이념-위의-건국과-그-이후의-전개","link":"#조선시대-성리학-이념-위의-건국과-그-이후의-전개","children":[]},{"level":2,"title":"왜 이렇게 공부하는가","slug":"왜-이렇게-공부하는가","link":"#왜-이렇게-공부하는가","children":[]}],"relativePath":"philosophy/Korean-Philosophy/01. 한국철학사 개관.md","filePath":"philosophy/Korean-Philosophy/01. 한국철학사 개관.md"}'),s={name:"philosophy/Korean-Philosophy/01. 한국철학사 개관.md"};function e(a,t,i,g,h,p){return r(),l("div",null,[...t[0]||(t[0]=[n('<h2 id="이-강의가-다루는-것" tabindex="-1">이 강의가 다루는 것 <a class="header-anchor" href="#이-강의가-다루는-것" aria-label="Permalink to &quot;이 강의가 다루는 것&quot;">​</a></h2><p>한국철학이 무엇이고, 그것이 어떤 배경과 문제의식에서 생겨났는지를 이해하는 것이 이 강의의 목적. 한국철학 전반을 백과사전식으로 훑는 것이 아니라, 그 가운데서도 핵심적인 사상적 논쟁들을 중심으로 다룸으로써 철학적 사고능력과 철학적 삶의 태도를 기르는 데 목표를 둠. 흔히 한국철학에 대해 갖는 &quot;중국철학을 우리식으로 바꾼, 현실과 동떨어진 고리타분한 학문&quot;이라는 이미지와 달리, 한국철학은 다른 나라에서 사상적 자원을 수용하면서도 그것을 한국 고유의 논리와 문제의식으로 재구성해 온 역사로 볼 수 있음.</p><h2 id="한국사상의-큰-흐름" tabindex="-1">한국사상의 큰 흐름 <a class="header-anchor" href="#한국사상의-큰-흐름" aria-label="Permalink to &quot;한국사상의 큰 흐름&quot;">​</a></h2><p>한국사상의 출발점은 <strong>단군신화</strong>다. 한반도 북부에 단군시대(기원전 2333년경)가 있었고, 이후 대륙(유교·도가/도교·불교)의 문화가 점차 한반도로 유입되기 시작함. 단군신화를 분석함으로써 한국인의 원형적 사고가 무엇인지를 먼저 살펴볼 수 있음.</p><p>유교·불교·도교가 들어오기 이전 한국 고유의 사상으로는 <strong>무교(巫敎)·무속신앙</strong>이 있었음. &quot;정월에 천신에게 제사를 드리는데 국민들이 대회를 열어 며칠씩 음식과 노래와 춤을 계속했다&quot;(영고), &quot;시월에는 천신에게 제사를 지내는데 온 나라가 대회를 열고 그 이름을 동맹이라고 했다&quot;, &quot;무천&quot; 등 여러 사서의 기록이 보여주듯, <strong>굿(무제)을 통해 재앙이나 병을 &#39;풀고&#39; 복을 &#39;비는&#39; 행위</strong>가 무속신앙의 핵심이며, 여기에서도 고유의 자연관·인간관·윤리관·공동체관을 읽어낼 수 있음.</p><h2 id="삼국시대-유교·불교·도교의-유입" tabindex="-1">삼국시대: 유교·불교·도교의 유입 <a class="header-anchor" href="#삼국시대-유교·불교·도교의-유입" aria-label="Permalink to &quot;삼국시대: 유교·불교·도교의 유입&quot;">​</a></h2><ul><li><strong>유교</strong>: 고구려 태학(소수림왕 2년, 372), 백제 박사제도(태학, 왕인이 일본에 유교를 전함), 신라 국학(신문왕 2년, 682).</li><li><strong>불교</strong>: 고구려 372년(순도, 북조 계통), 백제 384년(마라난타, 남조 계통), 신라 527년(고구려로부터, 이차돈 순교를 계기로 왕실 중심의 불교 공인). 이후 <strong>원효-화쟁</strong>, <strong>의상-화엄</strong>, <strong>원측-유식불교</strong>로 각각 특색 있는 신라 불교사상이 전개됨.</li><li><strong>도교/도가</strong>: 술수학(풍수지리, 양생술, 길흉점복 등)의 형태로 유입되어 천문학·의학 발전에 기여함. 도교는 고대 민간신앙에 &#39;신선설&#39;을 중심에 두고 도가·역리·음양·오행·참위·의술·점성 등의 법술을 더한 뒤 불교의 체제와 조직을 본떠 만들어진 종교로, 불로장생과 현세의 길복 추구를 목적으로 함 — 그런 만큼 유교·불교는 물론 다른 신앙까지 큰 마찰 없이 받아들여 포괄할 수 있었음.</li></ul><p>삼국시대에서 통일신라까지의 불교는 경전을 통해 깨달음을 얻으려는 <strong>교종</strong> 중심이었음.</p><h2 id="고려시대-성리학의-수용과-선종의-대두" tabindex="-1">고려시대: 성리학의 수용과 선종의 대두 <a class="header-anchor" href="#고려시대-성리학의-수용과-선종의-대두" aria-label="Permalink to &quot;고려시대: 성리학의 수용과 선종의 대두&quot;">​</a></h2><p>신라 말~고려 초, 왕권(교종)의 약화와 호족(선종) 세력의 성장, 도참사상·미륵신앙의 유행이라는 시대적 배경 속에서 <strong>선종</strong>이 정착됨. 고려 시기에는 중국으로부터 선종이 본격적으로 유입되어 <strong>의천이 교로 선을 통합</strong>하려 했고, 뒤이어 <strong>지눌이 선으로 교를 통합</strong>하는 방향으로 나아감.</p><p>한편 유교 쪽에서는 원(元)이 주자학을 관학화하고 『사서오경』을 과거 시험과목으로 지정하면서(1313년), 고려인들이 원의 과거에 응시하기 위해 『사서집주』를 익히는 과정에서 자연스럽게 성리학을 수용하게 됨. <strong>안향</strong>이 성리학을 도입한 상징적 인물로 꼽히며, 이후 백이정-권보-이제현-이곡-이색으로 이어지는 계보를 거쳐 이색 문하에서 <strong>정몽주·정도전·이숭인·길재·권근</strong> 등 신진사대부가 배출됨. 이들은 이후 이색·정몽주·이숭인·길재 등 <strong>온건파</strong>와 정도전·권근 등 <strong>급진파</strong>로 갈라지며, 급진파가 조선 건국을 주도하게 됨.</p><h2 id="조선시대-성리학-이념-위의-건국과-그-이후의-전개" tabindex="-1">조선시대: 성리학 이념 위의 건국과 그 이후의 전개 <a class="header-anchor" href="#조선시대-성리학-이념-위의-건국과-그-이후의-전개" aria-label="Permalink to &quot;조선시대: 성리학 이념 위의 건국과 그 이후의 전개&quot;">​</a></h2><p>조선은 성리학 이념 위에서 건국되었고, 성리학 이외의 학문을 이단시하는 강한 학문적 배타성을 지님. 다만 초기에는 왕실과 민간에서 여전히 불교를 신앙 차원에서 받아들이고 있었음.</p><p>조선 성리학은 이후 여러 세대에 걸쳐 심화되는데, 이 강의에서 다룰 주요 논쟁들은 다음과 같은 흐름으로 이어짐.</p><ul><li><strong>정도전</strong>: 성리학의 눈으로 불교(특히 리 개념의 부정)를 비판하며 조선 성리학의 기틀을 마련.</li><li><strong>이언적과 조한보의 무극태극논쟁</strong>(1517): 조선 최초의 체계적 개념 논쟁으로, 태극(리)의 소재와 그것을 얻는 공부법을 둘러싼 다툼.</li><li><strong>서경덕의 기철학</strong>과 <strong>조식의 실천철학</strong>: 리 중심의 흐름과는 결이 다른 기 중심의 사유, 실천 중심의 사유.</li><li><strong>이황과 기대승의 사단칠정논쟁</strong>: 사단·칠정과 리·기의 관계를 둘러싼 조선 성리학 최대의 논쟁.</li><li><strong>이이와 성혼의 인심도심논쟁</strong>: 사단칠정논쟁의 연장선에서 인심·도심 개념을 통해 리기론을 재검토.</li><li><strong>이간과 한원진의 호락논쟁</strong>(인물성동이논쟁): 인간과 동물의 본성이 같은가 다른가, 미발심체에 선악이 있는가를 둘러싼 논쟁.</li><li><strong>정약용의 성기호설</strong>: 성리학의 리기론적 인성론 자체를 해체하고, 성(性)을 실체가 아닌 심리적 기호(嗜好)로 재정의하는 실학적 인성론.</li></ul><p>이 밖에도 정제두의 양명학적 사유, 실학(정구-허목, 이수광-유형원-이익-정약용), 북학파(박지원-박제가), 고증학(김정희), 기철학(최한기), 위정척사(이항로-기정진), 동학(최제우), 개화파(김옥균-박영효) 등으로 한국사상의 흐름은 조선 후기~근대로 계속 이어짐.</p><h2 id="왜-이렇게-공부하는가" tabindex="-1">왜 이렇게 공부하는가 <a class="header-anchor" href="#왜-이렇게-공부하는가" aria-label="Permalink to &quot;왜 이렇게 공부하는가&quot;">​</a></h2><p>철학 수업의 특징은 비판적·반성적 사고에 있음 — ①문제의식을 갖고, ②그에 대한 자신의 판단과 견해를 세우고, ③그 판단과 견해를 합리적 근거로 뒷받침하는 과정. 한국철학사를 배운다는 것은 단순히 역사적 사실을 암기하는 것이 아니라, 위와 같은 사상적 논쟁들 속에서 각 논자가 어떤 문제의식을 가지고 어떤 논리로 상대를 설득하려 했는지를 따라가며 스스로 사유하는 훈련이라 할 수 있음.</p>',18)])])}const _=o(s,[["render",e]]);export{u as __pageData,_ as default};
